changeSet.sql:
create table expense_tracker.category ( id_pk bigint not null, created timestamp(6), deleted timestamp(6), updated timestamp(6), user_id_fk bigint, monthly_limit numeric(18, 8), description varchar(100) not null, name varchar(50) not null, primary key (id_pk) );
create sequence expense_tracker.category_sequence start with 1 increment by 50;
alter table if exists expense_tracker.category add foreign key(user_id_fk) references users(id_pk);
